def stamp(t):
    return t.isoformat().replace('+00:00', 'Z')


def date(s):
    return datetime.fromisoformat(s.replace('Z', '+00:00'))


def digest(b):
    return hashlib.sha256(b).hexdigest()


def runner_hash():
    return digest(Path(__file__).read_bytes())


def dump_json(p, value):
    p.write_text(json.dumps(value, indent=2, allow_nan=False)+'\n', encoding='utf-8')


def dump_csv(p, rows, fields=None):
    rows = list(rows)
    fields = fields or (list(rows[0]) if rows else ['status'])
    with p.open('w', encoding='utf-8', newline='') as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        w.writerows(rows)


def decode_csv(b, typed=False):
    rows = list(csv.DictReader(io.StringIO(b.decode('utf-8'))))
    if typed:
        for row in rows:
            for key, value in row.items():
                row[key] = None if value == '' else int(value) if key in INTEGERS else float(value) if key in FLOATS else value
    return rows


def ledger_hash(rows):
    return digest(''.join(json.dumps({k:r[k] for k in ROW_FIELDS}, sort_keys=True,
                                    separators=(',', ':'), allow_nan=False)+'\n'
                          for r in rows).encode())


class GateFailure(RuntimeError):
    pass


class Gates:
    def __init__(self):
        self.rows = []

    def check(self, name, actual, expected, numeric=False):
        passed = (isinstance(actual, (int, float)) and math.isfinite(actual)
                  and abs(actual-float(expected)) <= 1e-10) if numeric and expected is not None else actual == expected
        self.rows.append(dict(check=name, passed=passed, expected=expected, actual=actual))
        return passed

    def require(self):
        bad = [r['check'] for r in self.rows if not r['passed']]
        if bad:
            raise GateFailure(f'{len(bad)} failed checks: '+', '.join(bad[:8]))


def load_snapshot(gates):
    packed = base64.b85decode(REFERENCE_B85)
    gates.check('reference_archive_sha256', digest(packed), REFERENCE_SHA256)
    gates.require()
    with zipfile.ZipFile(io.BytesIO(packed)) as z:
        gates.check('reference_zip_integrity', z.testzip(), None)
        names = z.namelist()
        expected_names = {'file_manifest.json', 'frozen_definitions.json', 'frozen_expected_cases.csv',
                          'frozen_protocol.md', 'frozen_raw_signal_membership.csv',
                          'frozen_reference_ledgers.csv', 'frozen_signal_trade_paths.csv', 'source_candles.csv'}
        gates.check('exact_reference_members', set(names) == expected_names and len(names) == 8, True)
        gates.require()
        blobs = {name:z.read(name) for name in names}
    for item in json.loads(blobs['file_manifest.json']):
        b = blobs[item['file']]
        gates.check('bytes:'+item['file'], len(b), item['bytes'])
        gates.check('sha256:'+item['file'], digest(b), item['sha256'])
    frozen = json.loads(blobs['frozen_definitions.json'])
    gates.check('exact_frozen_rules', RULES, frozen['rules'])
    gates.check('closed_search', frozen['entry_and_rr_search_closed'], True)
    gates.require()
    candles = [(date(r['time']), *(float(r[k]) for k in ('open', 'high', 'low', 'close')))
               for r in decode_csv(blobs['source_candles.csv'])]
    gates.check('source_count', len(candles), 137819)
    gates.check('first_candle', stamp(candles[0][0]), frozen['first_candle'])
    gates.check('last_candle', stamp(candles[-1][0]), frozen['last_candle'])
    gates.check('end_exclusive', stamp(FINISH), frozen['end_exclusive'])
    good = all(BEGIN <= t < FINISH and t.minute == t.second == t.microsecond == 0
               and all(math.isfinite(x) and x > 0 for x in (o,h,l,c)) and l <= min(o,c) <= max(o,c) <= h
               and (i == 0 or t > candles[i-1][0]) for i,(t,o,h,l,c) in enumerate(candles))
    gates.check('completed_h1_source_geometry_and_order', good, True)
    canonical = '\n'.join(f'{stamp(t)},{o:.5f},{h:.5f},{l:.5f},{c:.5f}' for t,o,h,l,c in candles)
    gates.check('canonical_ohlc_sha256', digest(canonical.encode()), frozen['source_sha256'])
    gates.require()
    return candles, blobs, frozen


def scan_candles(candles):
    """Separately coded streaming Wilder ATR and direct prior-window scan."""
    atr = [None]*len(candles)
    seed = 0.0
    signals = {r['config_id']:[] for r in RULES}
    features = []
    patterns = 0
    for n in range(1, len(candles)):
        t,o,h,l,c = candles[n]
        pt,po,ph,pl,pc = candles[n-1]
        tr = max(h-l, abs(h-pc), abs(l-pc))
        if n <= 14:
            seed += tr
            if n == 14:
                atr[n] = seed/14
        else:
            atr[n] = (atr[n-1]*13+tr)/14
        if n < 200 or not (pc > po and c < o and o >= pc and c <= po):
            continue
        patterns += 1
        a = atr[n]
        high_before = max(bar[2] for bar in candles[n-60:n])
        span, prior_span = h-l, ph-pl
        if not a or span <= 0 or prior_span <= 0:
            continue
        body, size = abs(c-o)/a, span/a
        proximity = abs(h-high_before)/a
        location, prior_location = (c-l)/span, (pc-pl)/prior_span
        features.append(dict(signal_index=n,signal=stamp(t),atr14=a,prior60_high=high_before,
                             body_atr=body,range_atr=size,abs_high_distance_atr=proximity,
                             signal_close_location=location,previous_close_location=prior_location))
        for r in RULES:
            if (body >= r['body_min_atr'] and size >= r['range_min_atr']
                and proximity <= r['distance_atr'] and location <= r['signal_close_max']
                and (r['previous_close_min'] is None or prior_location >= r['previous_close_min'])):
                signals[r['config_id']].append(n)
    return signals, features, patterns, atr


def barrier_walk(candles, origin, reward, model):
    """Scan every subsequent OHLC candle for this isolated frozen signal."""
    t,_,h,_,c = candles[origin]
    protective = h + 10*TICK
    objective = c - reward*(protective-c)
    row = dict(signal_index=origin,signal=stamp(t),entry=stamp(t+HOUR),reference_entry=c,
               stop=protective,target=objective,
               next_open=candles[origin+1][1] if origin+1 < len(candles) else None,
               next_candle_delay_hours=(candles[origin+1][0]-t-HOUR).total_seconds()/3600
                   if origin+1 < len(candles) else None,
               exit_index=None,exit=None,exit_price=None,reason='OPEN_AT_DATA_END',
               dual_touch=0,gap_stop=0,gap_target=0)
    for n in range(origin+1, len(candles)):
        bt,opening,high,low,_ = candles[n]
        upper, lower = high >= protective, low <= objective
        if not (upper or lower):
            continue
        both = upper and lower
        time_out = bt+HOUR
        if model == 'SCREEN_PARITY':
            stop_wins = upper and (not lower or high-opening <= opening-low)
            label, price = ('STOP',protective) if stop_wins else ('TARGET',objective)
        elif model == 'STOP_FIRST_GAP_STRESS':
            if opening >= protective:
                label = 'STOP_GAP' if opening > protective else 'STOP'
                price, time_out = max(opening,protective), bt
            elif opening <= objective:
                label, price, time_out = 'TARGET_GAP_CAPPED', objective, bt
            else:
                label, price = ('STOP',protective) if upper else ('TARGET',objective)
        else:
            raise ValueError('Unknown execution model')
        row.update(exit_index=n,exit=stamp(time_out),exit_price=price,reason=label,
                   dual_touch=int(both),gap_stop=int(model != 'SCREEN_PARITY' and opening > protective),
                   gap_target=int(model != 'SCREEN_PARITY' and opening <= objective))
        break
    return row


def price_entry(path, cost):
    fill = path['reference_entry']-cost*TICK
    problem = ('ENTRY_AT_OR_AFTER_CUTOFF' if date(path['entry']) >= FINISH else
               'INVALID_FILL_STOP_TARGET_GEOMETRY' if not 0 < path['target'] < fill < path['stop'] else None)
    return fill, problem


def realized(path, cost):
    fill, problem = price_entry(path, cost)
    if problem or path['exit'] is None:
        return None
    return -1.0 if path['reason'] == 'STOP' else (fill-path['exit_price'])/(path['stop']-fill)


def chronological_orders(rule, positions, paths, model, cost):
    rows, rejected = [], []
    occupied_bar, blocked = -1, 0
    for n in positions:
        if n < occupied_bar:
            blocked += 1
            continue
        p = paths[n]
        fill, problem = price_entry(p, cost)
        if problem:
            rejected.append(dict(signal_index=n,reason=problem))
            continue
        rows.append(dict(config_id=rule['config_id'],execution_model=model,cost_ticks=cost,
                         accepted_sequence=len(rows)+1,signal_index=n,exit_index=p['exit_index'],
                         signal=p['signal'],entry=p['entry'],exit=p['exit'],reference_entry=p['reference_entry'],
                         historical_fill=fill,stop=p['stop'],target=p['target'],risk_price=p['stop']-fill,
                         exit_price=p['exit_price'],reason=p['reason'],r=realized(p,cost)))
        occupied_bar = math.inf if p['exit_index'] is None else p['exit_index']
    return rows, rejected, blocked


def performance(numbers):
    values = list(numbers)
    positive = [v for v in values if v > 0]
    negative = [v for v in values if v < 0]
    balance = maximum = drawdown = 0.0
    chain = longest = 0
    for v in values:
        balance += v
        maximum = max(maximum, balance)
        drawdown = min(drawdown,balance-maximum)
        chain = chain+1 if v < 0 else 0
        longest = max(longest,chain)
    return dict(closed_trades=len(values),wins=len(positive),losses=len(negative),
                win_rate_pct=100*len(positive)/len(values) if values else None,total_r=balance,
                expectancy_r=balance/len(values) if values else None,
                profit_factor=sum(positive)/-sum(negative) if negative else None,
                max_closed_dd_r=drawdown,max_losing_streak=longest)


def percentile(values, p):
    if not values:
        return None
    ordered = sorted(values)
    x = (len(ordered)-1)*p
    left, right = math.floor(x), math.ceil(x)
    return ordered[left]+(ordered[right]-ordered[left])*(x-left)


def boundaries():
    points = []
    y,m = BEGIN.year, BEGIN.month
    while datetime(y,m,1,tzinfo=UTC) <= FINISH:
        points.append(datetime(y,m,1,tzinfo=UTC))
        y,m = (y+1,1) if m == 12 else (y,m+1)
    return points


def periods():
    result = [(f'YEAR_{y}','calendar',datetime(y,1,1,tzinfo=UTC),min(datetime(y+1,1,1,tzinfo=UTC),FINISH)) for y in range(2005,2027)]
    result += [(f'ERA_{a}_{b-1}','era',datetime(a,1,1,tzinfo=UTC),min(datetime(b,1,1,tzinfo=UTC),FINISH)) for a,b in ((2005,2010),(2010,2016),(2016,2022),(2022,2027))]
    result += [(f'LATEST_{n}Y','recent',FINISH.replace(year=FINISH.year-n),FINISH) for n in (1,2,3,5,10)]
    result += [('CHF_PRE_FLOOR','policy_diagnostic',BEGIN,date('2011-09-06T00:00:00Z')),
               ('CHF_FLOOR_PERIOD','policy_diagnostic',date('2011-09-06T00:00:00Z'),date('2015-01-15T00:00:00Z')),
               ('CHF_2015_01_15','policy_diagnostic',date('2015-01-15T00:00:00Z'),date('2015-01-16T00:00:00Z')),
               ('CHF_AFTER_2015_01_15','policy_diagnostic',date('2015-01-16T00:00:00Z'),FINISH)]
    return result


def describe_case(rule, model, cost, indices, paths, rows, invalid, blocked):
    tag = dict(strategy_id=rule['strategy_id'],rr=rule['rr'],config_id=rule['config_id'],execution_model=model,cost_ticks=cost)
    closed = [r for r in rows if r['r'] is not None]
    closed_values = [r['r'] for r in closed]
    stamps = [(date(r['entry']),date(r['exit']) if r['exit'] else None,r) for r in rows]
    bounds = boundaries()
    months = [dict(tag,month=bounds[n].strftime('%Y-%m'),entry_count=0,exit_count=0,realized_r=0.0,
                   entry_cohort_eventual_r=0.0,entry_cohort_open=0) for n in range(len(bounds)-1)]
    for et,xt,r in stamps:
        bucket = bisect.bisect_right(bounds,et)-1
        months[bucket]['entry_count'] += 1
        if xt is None:
            months[bucket]['entry_cohort_open'] += 1
        else:
            months[bucket]['entry_cohort_eventual_r'] += r['r']
            cashbucket = bisect.bisect_left(bounds,xt)-1
            if not 0 <= cashbucket < len(months):
                raise GateFailure('Exit outside reporting bounds')
            months[cashbucket]['realized_r'] += r['r']
            months[cashbucket]['exit_count'] += 1
    period_rows = []
    posyears = negyears = emptyyears = 0
    for label,kind,a,b in periods():
        entrants = [r for et,xt,r in stamps if a <= et < b]
        settled = [r for et,xt,r in stamps if xt is not None and a < xt <= b]
        cohort = [r for r in entrants if r['r'] is not None]
        cohort_r = sum(r['r'] for r in cohort)
        p = performance(r['r'] for r in settled)
        partial = int(kind == 'calendar' and b == FINISH and FINISH.month != 1)
        period_rows.append(dict(tag,period=label,period_type=kind,start=stamp(a),end=stamp(b),partial_calendar_year=partial,
                                entry_count=len(entrants),entry_cohort_completed=len(cohort),entry_cohort_eventual_r=cohort_r,
                                entry_cohort_open=len(entrants)-len(cohort),exit_count=len(settled),realized_r=p['total_r'],
                                realized_max_dd_r=p['max_closed_dd_r'],
                                open_at_period_end=sum(et <= b and (xt is None or xt > b) for et,xt,r in stamps)))
        if kind == 'calendar' and not partial:
            posyears += cohort_r > 0
            negyears += cohort_r < 0
            emptyyears += not entrants
    cumulative = {k:[0] for k in ('entry_count','exit_count','realized_r')}
    for m in months:
        for k in cumulative:
            cumulative[k].append(cumulative[k][-1]+m[k])
    rolling, worst = [], {}
    for width in (12,24,36):
        candidates = []
        for end in range(width,len(bounds)):
            begin = end-width
            en,ex,cash = [cumulative[k][end]-cumulative[k][begin] for k in cumulative]
            candidates.append(dict(tag,months=width,start=stamp(bounds[begin]),end=stamp(bounds[end]),
                                   entry_count=en,exit_count=ex,realized_r=cash,zero_entry_window=int(en==0),zero_exit_window=int(ex==0)))
        lowest = min(candidates,key=lambda r:r['realized_r'])
        worst.update({f'worst_{width}m_realized_r':lowest['realized_r'],f'worst_{width}m_start':lowest['start'],
                      f'worst_{width}m_end':lowest['end'],f'zero_entry_{width}m_windows':sum(r['zero_entry_window'] for r in candidates)})
        rolling.extend(candidates)
    accepted_paths = [paths[r['signal_index']] for r in rows]
    closed_paths = [paths[r['signal_index']] for r in closed]
    entry_times = [et for et,_,_ in stamps]
    holding = [(date(r['exit'])-date(r['entry'])).total_seconds()/3600 for r in closed]
    stop_sizes = [p['stop']-p['reference_entry'] for p in accepted_paths]
    fractions = [cost*TICK/v for v in stop_sizes]
    streak = max_empty = 0
    for m in months:
        streak = streak+1 if m['entry_count'] == 0 else 0
        max_empty = max(max_empty,streak)
    isolated = [n for n in indices if price_entry(paths[n],cost)[1] is None]
    iso_values = [realized(paths[n],cost) for n in isolated if paths[n]['exit'] is not None]
    iso_stats = performance(iso_values)
    summary = dict(tag,raw_signals=len(indices),eligible_isolated_signals=len(isolated),isolated_completed=len(iso_values),
                   isolated_open=len(isolated)-len(iso_values),isolated_total_r=iso_stats['total_r'],isolated_profit_factor=iso_stats['profit_factor'],
                   geometry_invalid_all_signals=len(indices)-len(isolated),p0_blocked_signals=blocked,invalid_unblocked_entries=len(invalid),
                   open_at_data_end=len(rows)-len(closed),**performance(closed_values),
                   dual_touch_closed=sum(p['dual_touch'] for p in closed_paths),gap_stop_closed=sum(p['gap_stop'] for p in closed_paths),
                   gap_target_closed=sum(p['gap_target'] for p in closed_paths),
                   entry_next_open_gap_count=sum(p['next_open'] is not None and abs(p['next_open']-p['reference_entry']) > 0.5*TICK for p in accepted_paths),
                   entries_before_market_closure=sum((p['next_candle_delay_hours'] or 0) > 0 for p in accepted_paths),
                   median_stop_pips=percentile([v/0.0001 for v in stop_sizes],0.5),
                   median_cost_fraction_reference_risk=percentile(fractions,0.5),p90_cost_fraction_reference_risk=percentile(fractions,0.9),
                   median_holding_hours=percentile(holding,0.5),max_holding_hours=max(holding) if holding else None,
                   maximum_inter_entry_gap_days=max(((b-a).total_seconds()/86400 for a,b in zip(entry_times,entry_times[1:])),default=None),
                   leading_no_entry_days=((entry_times[0] if entry_times else FINISH)-BEGIN).total_seconds()/86400,
                   trailing_no_entry_days=(FINISH-(entry_times[-1] if entry_times else BEGIN)).total_seconds()/86400,
                   zero_entry_months=sum(m['entry_count'] == 0 for m in months),max_consecutive_zero_entry_months=max_empty,
                   positive_complete_entry_years=posyears,negative_complete_entry_years=negyears,zero_entry_complete_years=emptyyears,
                   raw_signal_sha256=digest('\n'.join(paths[n]['signal'] for n in indices).encode()),accepted_ledger_sha256=ledger_hash(rows),**worst)
    return summary, months, rolling, period_rows


def compare_fields(gates, label, actual, expected):
    gates.check(label+':row_count',len(actual),len(expected))
    for seq,(a,e) in enumerate(zip(actual,expected),1):
        gates.check(f'{label}:row{seq}:schema',set(a),set(e))
        for k,v in e.items():
            gates.check(f'{label}:row{seq}:{k}',a.get(k),v,numeric=isinstance(v,float))


def build_confirmation(candles, blobs, frozen, gates):
    indices, features, patterns, _ = scan_candles(candles)
    gates.check('raw_bearish_engulf_count', patterns, 9669)
    memberships = decode_csv(blobs['frozen_raw_signal_membership.csv'],True)
    for r,expected_count in zip(RULES,(59,118)):
        ours = indices[r['config_id']]
        theirs = [x['signal_index'] for x in memberships if x['config_id'] == r['config_id'] and x['rr'] == r['rr']]
        gates.check(r['role']+':qualifying_count',len(ours),expected_count)
        gates.check(r['role']+':complete_qualifying_indices',ours,theirs)
    gates.check('qualifying_membership_count',len(memberships),177)
    gates.require()
    expected = decode_csv(blobs['frozen_expected_cases.csv'])
    reference = decode_csv(blobs['frozen_reference_ledgers.csv'],True)
    reference_paths = decode_csv(blobs['frozen_signal_trade_paths.csv'],True)
    case_key = lambda r:(float(r['rr']),r['config_id'],r['execution_model'],int(r['cost_ticks']))
    wanted = {(r['rr'],r['config_id'],m,c) for r in RULES for m in MODELS for c in COSTS}
    gates.check('exact_expected_case_coverage',set(map(case_key,expected)) == wanted and len(expected) == 12,True)
    gates.check('reference_accepted_count',len(reference),1062)
    gates.check('reference_isolated_path_count',len(reference_paths),354)
    gates.require()
    outputs = defaultdict(list)
    outputs['pattern_features.csv'] = features
    for rule in RULES:
        ids = indices[rule['config_id']]
        outputs['raw_signal_membership.csv'] += [dict(rr=rule['rr'],config_id=rule['config_id'],signal_index=n) for n in ids]
        for model in MODELS:
            paths = {n:barrier_walk(candles,n,rule['rr'],model) for n in ids}
            actual_paths = [dict(rr=rule['rr'],execution_model=model,**paths[n]) for n in ids]
            expected_paths = [p for p in reference_paths if p['rr'] == rule['rr'] and p['execution_model'] == model]
            compare_fields(gates,rule['role']+':'+model+':isolated_paths',actual_paths,expected_paths)
            outputs['signal_trade_paths.csv'] += actual_paths
            for cost in COSTS:
                tag = dict(strategy_id=rule['strategy_id'],rr=rule['rr'],config_id=rule['config_id'],execution_model=model,cost_ticks=cost)
                key = case_key(tag)
                name = f'{rule["role"]}:{model}:{cost}'
                rows, rejected, blocked = chronological_orders(rule,ids,paths,model,cost)
                refrows = [{k:r[k] for k in ROW_FIELDS} for r in reference if case_key(r) == key]
                compare_fields(gates,name+':accepted',rows,refrows)
                summary,monthly,rolling,period = describe_case(rule,model,cost,ids,paths,rows,rejected,blocked)
                target = [r for r in expected if case_key(r) == key]
                gates.check(name+':single_expected_case',len(target),1)
                if len(target) == 1:
                    for field, val in target[0].items():
                        if field not in summary:
                            gates.check(name+':missing_summary:'+field,None,val)
                        elif val == '':
                            gates.check(name+':summary:'+field,summary[field],None)
                        elif isinstance(summary[field],(int,float)):
                            gates.check(name+':summary:'+field,summary[field],float(val),numeric=True)
                        else:
                            gates.check(name+':summary:'+field,summary[field],val)
                outputs['accepted_ledgers.csv'] += [dict(rr=rule['rr'],**r) for r in rows]
                outputs['summary.csv'].append(summary)
                outputs['monthly_results.csv'] += monthly
                outputs['rolling_windows.csv'] += rolling
                outputs['period_results.csv'] += period
                outputs['invalid_entries.csv'] += [dict(tag,**r) for r in rejected]
                outputs['open_at_data_end.csv'] += [dict(tag,signal_index=r['signal_index'],entry=r['entry'],historical_fill=r['historical_fill'],
                                                       stop=r['stop'],target=r['target'],held_hours_to_cutoff=(FINISH-date(r['entry'])).total_seconds()/3600)
                                                      for r in rows if r['exit'] is None]
                shock_start,shock_end = date('2015-01-15T00:00:00Z'),date('2015-01-16T00:00:00Z')
                outputs['chf_event_exposure.csv'] += [dict(tag,signal_index=r['signal_index'],entry=r['entry'],exit=r['exit'],eventual_r=r['r'],reason=r['reason'])
                                                     for r in rows if date(r['entry']) < shock_end and (r['exit'] is None or date(r['exit']) >= shock_start)]
                winners = sorted((r for r in rows if r['r'] is not None and r['r'] > 0),key=lambda r:r['r'],reverse=True)
                for top in (1,3,5):
                    contribution = sum(r['r'] for r in winners[:top])
                    gross = sum(r['r'] for r in winners)
                    outputs['influence.csv'].append(dict(tag,top_n=top,top_winning_r=contribution,gross_winning_share_pct=100*contribution/gross if gross else None,
                                                         descriptive_residual_r=summary['total_r']-contribution,interpretation='Descriptive influence, not a deletion strategy'))
    gates.check('produced_cases',len(outputs['summary.csv']),12)
    gates.check('produced_accepted_rows',len(outputs['accepted_ledgers.csv']),1062)
    gates.require()
    return outputs


def software_checks():
    g = Gates()
    t = date('2020-01-01T00:00:00Z')
    bars = [(t,1.002,1.003,0.999,1.0),(t+HOUR,1.000,1.004,0.989,1.001)]
    # Reference risk .0031; target .9907 atRR3.
    legacy = barrier_walk(bars,0,3.0,'SCREEN_PARITY')
    stress = barrier_walk(bars,0,3.0,'STOP_FIRST_GAP_STRESS')
    g.check('dual_touch_nearer_high_stop',legacy['reason'],'STOP')
    g.check('stress_dual_touch_stop',stress['reason'],'STOP')
    bars[1] = (t+HOUR,1.0,1.02,0.989,1.0)
    g.check('dual_touch_nearer_low_target',barrier_walk(bars,0,3.0,'SCREEN_PARITY')['reason'],'TARGET')
    bars[1] = (t+HOUR,1.0,1.02,0.98,1.0)
    g.check('dual_touch_equal_distance_tie_stop',barrier_walk(bars,0,3.0,'SCREEN_PARITY')['reason'],'STOP')
    bars[1] = (t+HOUR,1.005,1.006,1.004,1.005)
    gap = barrier_walk(bars,0,3.0,'STOP_FIRST_GAP_STRESS')
    g.check('stop_gap_price',gap['exit_price'],1.005)
    g.check('stop_gap_timestamp',gap['exit'],stamp(t+HOUR))
    g.check('stop_gap_loss_beyond_one',realized(gap,10) < -1,True)
    bars[1] = (t+HOUR,0.98,0.985,0.975,0.98)
    capped = barrier_walk(bars,0,3.0,'STOP_FIRST_GAP_STRESS')
    g.check('target_gap_capped',capped['exit_price'],capped['target'])
    g.check('target_gap_reason',capped['reason'],'TARGET_GAP_CAPPED')
    bars[1] = (t+HOUR,1.001,1.002,0.999,1.001)
    opened = barrier_walk(bars,0,3.5,'SCREEN_PARITY')
    g.check('unresolved_has_no_exit',opened['exit_index'],None)
    g.check('unresolved_has_no_r',realized(opened,10),None)
    paths = {0:opened,1:opened}
    accepted,bad,blocked = chronological_orders(RULES[0],[0,1],paths,'SCREEN_PARITY',10)
    g.check('open_trade_keeps_p0', (len(accepted),len(bad),blocked),(1,0,1))
    exitpath = dict(opened,exit_index=1,exit=stamp(t+2*HOUR),exit_price=opened['stop'],reason='STOP')
    paths = {0:exitpath,1:opened}
    g.check('exit_candle_reentry',len(chronological_orders(RULES[0],[0,1],paths,'SCREEN_PARITY',10)[0]),2)
    tight = dict(opened,reference_entry=1.0,stop=1.0002,target=0.9998)
    g.check('adverse_cost_invalid_geometry',price_entry(tight,40)[1],'INVALID_FILL_STOP_TARGET_GEOMETRY')
    g.check('occupancy_precedes_invalid_geometry',chronological_orders(RULES[0],[0,1],{0:opened,1:tight},'SCREEN_PARITY',40)[1],[])
    late = dict(opened,entry=stamp(FINISH))
    g.check('cutoff_entry_invalid',price_entry(late,10)[1],'ENTRY_AT_OR_AFTER_CUTOFF')
    g.check('ordinary_stop_exact_negative_one',realized(exitpath,40),-1.0)
    narrow = [(t,1.002,1.003,0.999,1.0),(t+HOUR,1.0,1.001,0.990,0.995)]
    g.check('rr_target_changes_first_barrier',(barrier_walk(narrow,0,3.0,'SCREEN_PARITY')['reason'],barrier_walk(narrow,0,3.5,'SCREEN_PARITY')['reason']),('TARGET','OPEN_AT_DATA_END'))
    series = [(t+n*HOUR,1.0,1.01,0.99,1.0) for n in range(202)]
    _,_,patterns,atr = scan_candles(series)
    g.check('atr_seed_first_fourteen',atr[14],0.02,numeric=True)
    g.check('atr_recursion',atr[201],0.02,numeric=True)
    g.check('atr_no_preseed_value',atr[13],None)
    g.check('non_engulf_zero_patterns',patterns,0)
    series[199] = (t+199*HOUR,1.0,1.01,0.99,1.006)
    series[200] = (t+200*HOUR,1.006,1.02,0.98,0.981)
    _,f,_,_ = scan_candles(series)
    g.check('prior_high_excludes_signal',f[0]['prior60_high'],1.01)
    prefix_atr = scan_candles(series[:201])[3]
    g.check('atr_causal_prefix',prefix_atr,scan_candles(series)[3][:201])
    warm = [(t+n*HOUR,1.0,1.01,0.99,1.0) for n in range(201)]
    warm[198] = (t+198*HOUR,1.0,1.01,0.99,1.006)
    warm[199] = (t+199*HOUR,1.006,1.01,0.98,0.981)
    g.check('warmup_199_bearish_engulf_excluded',scan_candles(warm)[2],0)
    fixture = [(t+n*HOUR,1.0,1.01,0.99,1.0) for n in range(201)]
    fixture[199] = (t+199*HOUR,1.0,1.01,0.99,1.006)
    fixture[200] = (t+200*HOUR,1.006,1.011,0.985,0.987)
    streams,_,_,_ = scan_candles(fixture)
    g.check('frozen_primary_qualifying_fixture',streams[RULES[0]['config_id']],[200])
    g.check('frozen_comparator_qualifying_fixture',streams[RULES[1]['config_id']],[200])
    fixture[199] = (t+199*HOUR,1.0,1.01,0.99,1.002)
    fixture[200] = (t+200*HOUR,1.004,1.01,0.98,0.983)
    streams,_,_,_ = scan_candles(fixture)
    g.check('primary_requires_previous_close',streams[RULES[0]['config_id']],[])
    g.check('comparator_has_no_previous_close_filter',streams[RULES[1]['config_id']],[200])
    fixture[200] = (t+200*HOUR,1.004,1.004,0.98,0.983)
    g.check('absolute_distance_below_prior_high',scan_candles(fixture)[1][0]['abs_high_distance_atr'] > 0.1,True)
    g.check('monthly_zero_windows_present',len(boundaries())-1,261)
    g.check('loss_drawdown_streak',performance([2,-1,-1,3])['max_closed_dd_r'],-2.0)
    g.check('cost_is_adverse_short_fill',price_entry(opened,40)[0],opened['reference_entry']-0.0004)
    g.require()
    return g.rows


def read_status():
    try:
        return json.loads((OUT/'status.json').read_text(encoding='utf-8'))
    except (OSError,ValueError):
        return dict(state='idle',version=VERSION)


def write_status(state, **values):
    OUT.mkdir(parents=True,exist_ok=True)
    value = dict(state=state,version=VERSION,runner_sha256=runner_hash(),updated=stamp(datetime.now(UTC)),**values)
    with tempfile.NamedTemporaryFile(dir=OUT,delete=False,mode='w',encoding='utf-8') as f:
        json.dump(value,f,allow_nan=False)
        name = f.name
    os.replace(name,OUT/'status.json')


def publish(work, success):
    allowed = {'protocol.md','run_manifest.json','error_report.json','parity_checks.csv','software_checks.csv','runner_source.py'}
    members = [p for p in sorted(work.iterdir()) if p.is_file() and p.name != 'file_manifest.json' and (success or p.name in allowed)]
    dump_json(work/'file_manifest.json',[dict(file=p.name,bytes=p.stat().st_size,sha256=digest(p.read_bytes())) for p in members])
    fd,name = tempfile.mkstemp(dir=OUT,suffix='.zip')
    os.close(fd)
    try:
        with zipfile.ZipFile(name,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
            for p in members+[work/'file_manifest.json']:
                z.write(p,p.name)
        os.replace(name,OUT/RESULT_NAME)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def confirmation_job():
    global FILE_LOCK
    gates = Gates()
    success = False
    manifest = dict(version=VERSION,status='RUNNING',runner_sha256=runner_hash(),reference_archive_sha256=REFERENCE_SHA256,
                    cases_expected=12,history_is_in_sample=True,orders_supported=False,portfolio_admission_complete=False)
    try:
        with tempfile.TemporaryDirectory(prefix='confirmation-',dir=OUT) as folder:
            work = Path(folder)
            (work/'protocol.md').write_text(PROTOCOL,encoding='utf-8')
            (work/'runner_source.py').write_bytes(Path(__file__).read_bytes())
            try:
                software = software_checks()
                dump_csv(work/'software_checks.csv',software)
                write_status('running',progress=10,message='Verifying frozen inputs and rebuilding OHLC signals',result_path=None)
                candles,blobs,frozen = load_snapshot(gates)
                write_status('running',progress=30,message='Independent barriers, cost chronology, full-field parity and reports',result_path=None)
                outputs = build_confirmation(candles,blobs,frozen,gates)
                for name,rows in outputs.items():
                    dump_csv(work/name,rows)
                # Explicit empty diagnostic schemas; never hide a zero-row report.
                for name,fields in {
                    'invalid_entries.csv':['strategy_id','rr','config_id','execution_model','cost_ticks','signal_index','reason'],
                    'open_at_data_end.csv':['strategy_id','rr','config_id','execution_model','cost_ticks','signal_index','entry','historical_fill','stop','target','held_hours_to_cutoff'],
                    'chf_event_exposure.csv':['strategy_id','rr','config_id','execution_model','cost_ticks','signal_index','entry','exit','eventual_r','reason']}.items():
                    if not outputs[name]:
                        dump_csv(work/name,[],fields)
                (work/'source_candles.csv').write_bytes(blobs['source_candles.csv'])
                (work/'frozen_definitions.json').write_bytes(blobs['frozen_definitions.json'])
                (work/'frozen_expected_cases.csv').write_bytes(blobs['frozen_expected_cases.csv'])
                dump_csv(work/'coverage.csv',[dict(price_type=frozen['price_type'],candles=len(candles),first=stamp(candles[0][0]),
                                                  last=stamp(candles[-1][0]),end_exclusive=stamp(FINISH),source_sha256=frozen['source_sha256'],warmup=200)])
                dump_csv(work/'data_gaps.csv',[dict(previous=stamp(a[0]),following=stamp(b[0]),missing_wall_hours=(b[0]-a[0]).total_seconds()/3600-1)
                                               for a,b in zip(candles,candles[1:]) if b[0]-a[0] != HOUR],['previous','following','missing_wall_hours'])
                manifest.update(status='COMPLETE',cases=12,accepted_rows=1062,raw_memberships=177,isolated_paths=354,
                                independent_confirmation_complete=True,software_checks=len(software),parity_checks=len(gates.rows),
                                output_row_counts={k:len(v) for k,v in outputs.items()})
                success = True
            except Exception as exc:
                manifest.update(status='ERROR',independent_confirmation_complete=False,error=str(exc))
                dump_json(work/'error_report.json',dict(error=str(exc),traceback=traceback.format_exc(),
                                                       interpretation='Failed gate; no partial performance or portfolio interpretation'))
            dump_csv(work/'parity_checks.csv',gates.rows,['check','passed','expected','actual'])
            manifest['completed_utc'] = stamp(datetime.now(UTC))
            dump_json(work/'run_manifest.json',manifest)
            publish(work,success)
            write_status('complete' if success else 'error',progress=100,manifest=manifest,result_path=RESULT_NAME,
                         result_sha256=digest((OUT/RESULT_NAME).read_bytes()),message='Complete exact ledger parity' if success else 'Gate failed; download error ZIP')
    except Exception as exc:
        write_status('error',progress=100,result_path=None,message='Result publication failed: '+str(exc))
        success = False
    finally:
        if FILE_LOCK is not None:
            FILE_LOCK.close()
            FILE_LOCK = None
    return success


def launch(background=True):
    global STARTED, FILE_LOCK
    with MUTEX:
        if STARTED:
            return False
        OUT.mkdir(parents=True,exist_ok=True)
        if os.name == 'posix':
            import fcntl
            handle = (OUT/'run.lock').open('a+')
            try:
                fcntl.flock(handle,fcntl.LOCK_EX|fcntl.LOCK_NB)
            except BlockingIOError:
                handle.close()
                return False
            FILE_LOCK = handle
        prior = read_status()
        bundle = OUT/RESULT_NAME
        if prior.get('state') == 'complete' and prior.get('runner_sha256') == runner_hash() and bundle.exists() and digest(bundle.read_bytes()) == prior.get('result_sha256'):
            STARTED = True
            if FILE_LOCK is not None:
                FILE_LOCK.close()
                FILE_LOCK = None
            return False
        STARTED = True
        write_status('starting',progress=0,message='Independent frozen-strategy confirmation',result_path=None)
    if background:
        threading.Thread(target=confirmation_job,name='eurchf-independent',daemon=True).start()
        return True
    return confirmation_job()


def app(environ,start_response):
    path = environ.get('PATH_INFO','/')
    if path.startswith(PREFIX+'/') or path == PREFIX:
        path = path[len(PREFIX):] or '/'
    method = environ.get('REQUEST_METHOD','GET')
    if method not in ('GET','HEAD'):
        code, value = '405 Method Not Allowed',dict(error='GET or HEAD only')
    elif path not in ('/','/start','/status','/health','/results'):
        code, value = '404 Not Found',dict(error='Not found')
    else:
        if method == 'GET' and (path == '/start' or os.getenv('EURCHF_PASS7_AUTOSTART','1') == '1') and not STARTED:
            launch()
        value,code = read_status(),'200 OK'
        if path == '/results':
            bundle = OUT/RESULT_NAME
            if value.get('state') in ('complete','error') and value.get('runner_sha256') == runner_hash() and value.get('result_path') and bundle.exists():
                start_response(code,[('Content-Type','application/zip'),('Content-Length',str(bundle.stat().st_size)),
                                     ('Content-Disposition',f'attachment; filename="{RESULT_NAME}"'),('Cache-Control','no-store')])
                if method == 'HEAD':
                    return []
                def blocks():
                    with bundle.open('rb') as f:
                        while True:
                            chunk = f.read(1024*1024)
                            if not chunk:
                                break
                            yield chunk
                return blocks()
            code = '409 Conflict'
            value = dict(value,error='Results not ready for this code version')
        elif path == '/health':
            value = dict(ok=True,state=value.get('state'),version=VERSION,orders_supported=False)
        elif path == '/':
            value = dict(service='EUR/CHF independent confirmation',version=VERSION,state=value.get('state'),status='/status',results='/results',orders_supported=False)
    body = (json.dumps(value,allow_nan=False)+'\n').encode()
    start_response(code,[('Content-Type','application/json'),('Content-Length',str(len(body))),('Cache-Control','no-store')])
    return [] if method == 'HEAD' else [body]


class ConcurrentServer(ThreadingMixIn,WSGIServer):
    daemon_threads = True


def main():
    p = argparse.ArgumentParser(description=__doc__)
    args = p.add_mutually_exclusive_group()
    args.add_argument('--run',action='store_true')
    args.add_argument('--self-test',action='store_true')
    selected = p.parse_args()
    if selected.self_test:
        print(json.dumps(dict(version=VERSION,market_data_used=False,checks=software_checks()),indent=2))
        return 0
    if selected.run:
        launch(background=False)
        print(json.dumps(read_status(),indent=2))
        return 0 if read_status().get('state') == 'complete' else 1
    if os.getenv('EURCHF_PASS7_AUTOSTART','1') == '1':
        launch()
    with make_server('0.0.0.0',int(os.getenv('PORT','8080')),app,server_class=ConcurrentServer) as server:
        print(VERSION+': /status and /results',flush=True)
        server.serve_forever()
    return 0


